-- Mod-authored era splash painting descriptions, fr_FR overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Aucune description pour cette ère."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Un grand temple à colonnes se dresse au sommet d'une colline en terrasses ; de plus petits portiques à colonnes descendent à sa droite. Des jardins grimpent la pente en dessous, où d'étroits escaliers serpentent le long d'un éperon de roche pâle couronné de cyprès et d'arbustes en fleurs. Tout le marbre brille d'un or chaud sous le soleil."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Des champs de blé dorés s'étendent sous une ville close de tours pâles sur une colline. Des bannières rouges pendent de ses créneaux ; la plus grande porte un oiseau noir aux ailes déployées. C'est le temps des moissons : des paysans courbés ramassent le grain coupé, d'autres portent de hautes gerbes sur leur dos, et des ouvriers au centre chargent une charrette attelée à une paire de bœufs noirs. Des arbres se penchent dans les coins supérieurs sous un ciel doux et voilé."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Haut au-dessus des toits de Florence, Michel-Ange se tient sur une échelle en bois et sculpte le colossal David de marbre blanc. La tête et les épaules seules de la statue occupent la gauche du cadre ; le sculpteur arrive à peine à la hauteur de l'épaule. En contrebas, les toits de tuiles rouges s'étendent jusqu'au grand dôme de la cathédrale de Florence et à un élégant campanile. Derrière eux, une lumière dorée perce un ciel sombre d'orage."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Un bateau à roues à aubes rouge et blanc traverse le port de New York au premier plan, laissant derrière lui la fumée de deux cheminées noires. Des passagers s'alignent sur ses deux ponts. Derrière lui, la Statue de la Liberté se dresse, verte, contre un ciel ambré et brumeux ; d'autres navires à vapeur sillonnent l'eau au-delà. Fumée et brume teintent toute la scène de sépia chaud et d'or."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "Le regard porte depuis le toit d'une tour sur une ville qui en est hérissée. Des tours illuminées reculent pâté après pâté dans une brume dorée. Loin en contrebas, des autoroutes surélevées s'entrelacent dans un échangeur que parcourent voitures et camions. Tout le tableau est d'une seule couleur, or et sépia comme une photographie teintée."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Un soleil bas flamboie au fond d'une rue du centre-ville des années cinquante et la noie de lumière dorée. Des hommes en costume et chapeau fedora marchent sur le trottoir de droite, dos au spectateur, longeant des auvents et une grande marquise à lettres. De sombres berlines aux formes arrondies stationnent le long du trottoir ou passent lentement. Plus loin, les immeubles se dissolvent dans l'éclat."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Une ville futuriste brille le long d'un littoral doré, ses élancées tours s'effaçant vers le fond de la côte dans la brume. À gauche, un élégant avion à réaction rouge et blanc vire au-dessus de l'eau ; derrière lui, un pont suspendu enjambe la baie. Au premier plan à droite, un ensemble de chrome et de verre coiffé d'un dôme est bâti à même les falaises côtières. Des plantes vertes garnissent ses terrasses ; une silhouette solitaire se tient sur une passerelle."
